import Image from "next/image";
import Link from "next/link";
import { ShoppingBag, BookOpen } from "lucide-react";
import { getPublishedBooks } from "@/lib/content";
import { BookStats } from "./BookStats";
import { SiteLogo } from "@/components/SiteLogo";

// Reader-facing copy for the flagship book — written in second person so it
// speaks directly to the person about to read it.
const READER_DESCRIPTION = [
  "If you feel stuck, overthinking every decision, or exhausted from fighting your own thoughts — this book was written for you.",
  "You'll learn the one simple shift to stop resisting your mind and start aligning with it. In a few hours, you'll see stress, relationships, work and self-doubt differently.",
  "No overnight transformation. Just one unshakable mindset.",
];

export async function MindUpBook() {
  const books = await getPublishedBooks("PUBLISHED");
  // Homepage shows the flagship MIND UP Theory book only.
  const book = books.find((b) => b.title.toLowerCase().includes("mind up theory"));

  if (!book) return null;

  return (
    <section
      className="relative overflow-hidden border-b border-border bg-background"
      aria-label="The MIND UP Theory book"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-20 md:py-24">
        <article className="flex flex-col md:flex-row items-center gap-8 md:gap-12 lg:gap-16">
          {/* Book cover — centered on mobile */}
          <div data-animate-item className="w-full md:w-2/5 lg:w-2/5 shrink-0 flex justify-center">
            <div className="relative aspect-[3/4] w-[70vw] max-w-[300px] md:w-full">
              {book.imageUrl ? (
                <Image
                  src={book.imageUrl}
                  alt={book.title}
                  fill
                  sizes="(max-width: 768px) 70vw, 400px"
                  className="object-contain drop-shadow-lg"
                />
              ) : (
                <div className="w-full h-full grid place-items-center rounded-3xl bg-muted p-6">
                  <span className="font-display text-xl font-bold text-foreground text-center">
                    {book.title}
                  </span>
                </div>
              )}
            </div>
          </div>

          {/* Book story */}
          <div data-animate-item className="w-full md:flex-1 text-left">
            <p className="text-[10px] font-semibold uppercase tracking-wider text-accent-strong">
              {book.tagline ?? "The flagship book"}
            </p>
            <h3 className="mt-2 font-display text-2xl md:text-3xl font-bold leading-snug">
              {book.title}
            </h3>
            <p className="mt-4 text-sm md:text-base leading-relaxed text-muted-foreground max-w-xl whitespace-pre-line">
              {READER_DESCRIPTION.join("\n")}
            </p>

            <div className="mt-7 inline-block">
              <SiteLogo className="h-9 w-auto" />
            </div>
            <div className="mt-4 flex flex-wrap items-center gap-4">
              <a
                href={book.buyUrl ?? "/books"}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center justify-center gap-2 rounded-full bg-accent text-accent-foreground px-5 py-2.5 text-sm font-semibold shadow-sm hover:opacity-90 transition-opacity"
              >
                <ShoppingBag className="w-4 h-4" />
                Get your Copy
              </a>
              <Link
                href="/books"
                className="inline-flex items-center gap-1.5 text-sm font-semibold hover:underline underline-offset-4"
              >
                <BookOpen className="w-4 h-4" />
                Read more about this book
              </Link>
            </div>
          </div>
        </article>
      </div>

      {/* Author Stats Bar */}
      <div className="border-t border-border">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 py-12 md:py-14">
          <BookStats />
        </div>
      </div>
    </section>
  );
}